"""Original cubic drawings for this reference study. No existing font outlines or raster tracing.
All coordinates are on the project template: baseline 800, x-height 380, cap 80.
"""
import json
from pathlib import Path
from fontTools.pens.recordingPen import RecordingPen
from fontTools.pens.reverseContourPen import ReverseContourPen
from fontTools.pens.svgPathPen import SVGPathPen
from fontTools.svgLib.path import parse_path

OUT = Path(__file__).resolve().parent
D = {}
def glyph(name, width, outline, *holes):
    # Outer and counter drawings are authored clockwise in SVG. Reverse counters explicitly.
    paths = [outline] if outline else []
    for hole in holes:
        pen = SVGPathPen(None)
        parse_path(hole, ReverseContourPen(pen))
        paths.append(pen.getCommands())
    D[name] = (width, ' '.join(paths))

