# Initial gate is deliberately the reference text and construction controls.
ROOT = OUT / 'font'
template = (ROOT / 'glyph-template.svg').read_text()
source_dir = OUT / 'drawings'
source_dir.mkdir(exist_ok=True)
items = []
char_map = {'space':' ', 'period':'.', 'comma':',', 'hyphen':'-', 'quotesingle':"'"}
for name, (width, data) in D.items():
    # Codepoint filenames avoid collisions on case-insensitive macOS filesystems.
    char = char_map.get(name, name)
    source = source_dir / (f'u{ord(char):04x}.svg' if len(char) == 1 else f'{name}.svg')
    source.write_text(template.replace('<g id="glyph" fill="#000000"></g>', f'<g id="glyph" fill="#000000"><path d="{data}"/></g>' if data else '<g id="glyph" fill="#000000"></g>'))
    items.append({'name':name, 'svg_path':str(source), 'codepoints':[f'U+{ord(char):04X}'] if len(char) == 1 else [], 'advance_width':width})
(OUT / 'glyphs.json').write_text(json.dumps(items, indent=2))
print(f'Drew {len(items)} original glyphs')
